package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class IsResourceServerVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property is resource server of trusted client ")
  void test_is_resource_server_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> IsResourceServerVO.tryFrom(null));
    Assertions.assertEquals(true, IsResourceServerVO.from(true).isIsResourceServer());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> IsResourceServerVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", IsResourceServerVO.from(true).toString());
  }
}
